import numpy as np
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
one=np.ones_like(t)
lin=[one,x,v,x**2,v**2,x*v,x**3,v**3,x*v*v,x*x*v]
def score(g):
    A=np.column_stack(lin+[g]); c,_,_,_=np.linalg.lstsq(A,a,rcond=None); r=a-A@c
    return np.mean(r**2)/np.var(a)
res=[]
for k in np.linspace(0.1,5,50): res.append((score(np.exp(-k*t)),'exp',k))
for p in np.linspace(0.5,4,36): res.append((score(t**-p),'pow',p))
for c0 in np.linspace(0,3,31): res.append((score(1/(t+c0)),'1/(t+c)',c0))
for k in np.linspace(0.1,3,30): res.append((score(np.exp(-k*t)/t),'exp/t',k))
res.sort(key=lambda z:z[0]); print(res[:8])

